import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const SignInPage = () => {
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (user) {
      navigate('/account');
    }
  }, []);

  const signIn = async () => {
    const result = await signInRequest();
    setUser(result.user);
  };

  return <SignInForm onSubmit={signIn} />;
};

